#!/usr/bin/env python3
"""Generate stft_ref.txt: reference values for stem-audio's Stft.

torch is not available here, so this is a float64 numpy transcription of
torch.stft(x, n_fft, hop, window=torch.hann_window(n_fft), center=True, pad_mode="reflect",
normalized=False, onesided=True, return_complex=True) and of torch.istft(..., length=len),
following torch/functional.py and aten/src/ATen/native/SpectralOps.cpp:
  - center: reflect-pad n_fft // 2 on both sides (np.pad mode="reflect", no edge repeat)
  - frames = 1 + (padded_len - n_fft) // hop, each frame multiplied by the periodic Hann window
  - istft: irfft(n=n_fft) * window, overlap-add, divide by overlap-added window**2,
    drop n_fft // 2 samples from the start, keep `length` samples.

Usage (from this directory): python3 gen_stft_ref.py > stft_ref.txt
The test signal and mask must match `test_signal` / `mask` in src/stft.rs.
"""
import numpy as np

CASES = [(16, 4, 50), (12, 5, 37), (15, 4, 41), (32, 8, 100)]


def signal(n):
    i = np.arange(n, dtype=np.float64)
    return np.sin(0.3 * i) + 0.5 * np.cos(1.7 * i + 0.2) + 0.1 * (np.arange(n) % 7) - 0.3


def hann(n):
    return 0.5 - 0.5 * np.cos(2 * np.pi * np.arange(n) / n)


def stft(x, n_fft, hop):
    pad = n_fft // 2
    xp = np.pad(x, pad, mode="reflect")
    w = hann(n_fft)
    n_frames = 1 + (len(xp) - n_fft) // hop
    return np.stack([np.fft.rfft(xp[f * hop:f * hop + n_fft] * w) for f in range(n_frames)])


def istft(spec, n_fft, hop, length):
    w = hann(n_fft)
    n_frames = spec.shape[0]
    total = n_fft + hop * (n_frames - 1)
    y = np.zeros(total)
    env = np.zeros(total)
    for f in range(n_frames):
        y[f * hop:f * hop + n_fft] += np.fft.irfft(spec[f], n=n_fft) * w
        env[f * hop:f * hop + n_fft] += w * w
    start = n_fft // 2
    y = y[start:start + length]
    env = env[start:start + length]
    out = np.zeros(length)
    out[:len(y)] = y / env
    return out


def mask(frames, bins):
    f = np.arange(frames)[:, None].astype(np.float64)
    b = np.arange(bins)[None, :].astype(np.float64)
    return 0.5 + 0.5 * np.sin(f * 0.7 + b * 1.3)


print("# generated by gen_stft_ref.py; per case: header, spectrum (re im ...), masked istft")
for n_fft, hop, n in CASES:
    x = signal(n)
    s = stft(x, n_fft, hop)
    frames, bins = s.shape
    y = istft(s * mask(frames, bins), n_fft, hop, n)
    print(f"case {n_fft} {hop} {n} {frames} {bins}")
    print(" ".join(f"{v.real:.9g} {v.imag:.9g}" for v in s.reshape(-1)))
    print(" ".join(f"{v:.9g}" for v in y))
